(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.25)*18+Math.sin(x*0.016+t*0.32)*12;
  const w2x = Math.sin(w1x*0.025+t*0.5)*8+Math.cos(w1y*0.03-t*0.4)*6;
  const w2y = Math.cos(w1y*0.028-t*0.45)*8+Math.sin(w1x*0.022+t*0.55)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.65+3)*70,40+Math.cos(t*0.75+1)*50,0.11,2.1],
    [400+Math.cos(t*0.45+2)*60,200+Math.sin(t*0.85+4)*70,0.085,1.8]
  ];
  let act=0,inh1=0,inh2=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    act+=Math.sin(d*f-t*sp);
    inh1+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    inh2+=Math.sin(d*f*1.3-t*sp*0.4+3.0);
  }
  act/=8;inh1/=8;inh2/=8;
  const bg1=Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1);
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.3+Math.sin((sx-sy)*0.1-t*2)*0.3;
  const n1=Math.sin(sx*0.08+Math.sin(sy*0.06+t)*2+t*0.3);
  const n2=Math.sin(sy*0.09+Math.sin(sx*0.07-t*0.5)*2-t*0.4);
  const bg=(bg1/2+bg2+(n1+n2)*0.3)/2.3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.065-ang*2+t*0.8)*0.5)/2.5;
  const cell=(Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*Math.sin((sx-sy)*0.08-t*0.7)*0.5)/1.5;
  const rd1=act-inh1*0.6+bg*0.25+spiral*0.4;
  const rd2=act*0.8-inh2*0.5+cell*0.3+bg*0.15;
  const reaction=Math.tanh(rd1*2.0+rd2*0.8);
  const micro=Math.sin(sx*0.3+reaction*3)*Math.sin(sy*0.25-reaction*2)*0.15;
  const blend=reaction*0.7+Math.tanh(cell*1.5)*0.15+micro;
  const v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,45,95],[18,90,120],[25,150,130],[120,185,90],[210,195,60],[230,140,50],[210,85,55],[170,45,60],[100,25,55],[50,15,65],[6,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i,sf=f*f*(3-2*f);
  const c0=pal[i],c1=pal[i+1];
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+Math.abs(micro)*0.3;
  const ar=Math.abs(reaction);
  const edge=ar>0.75?1.0+(ar-0.75)*1.2:ar>0.5?1.0+(ar-0.5)*0.15:0.95+ar*0.1;
  const vig=1.0-Math.sqrt((x-cx)**2+(y-cy)**2)/350*0.15;
  const br=lum*edge*vig;
  return[Math.min(255,(c0[0]+(c1[0]-c0[0])*sf)*br)|0,Math.min(255,(c0[1]+(c1[1]-c0[1])*sf)*br)|0,Math.min(255,(c0[2]+(c1[2]-c0[2])*sf)*br)|0];
